CREATE FUNCTION public.protect_company_features() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.enabled_modules IS DISTINCT FROM OLD.enabled_modules OR NEW.demo_mode IS DISTINCT FROM OLD.demo_mode THEN IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Platform administrator required to change company features' USING ERRCODE='42501'; END IF; PERFORM public.validate_company_modules(to_jsonb(NEW.enabled_modules)); END IF; RETURN NEW; END $$; CREATE TRIGGER protect_company_features BEFORE UPDATE ON public.organizations FOR EACH ROW EXECUTE FUNCTION public.protect_company_features();